-- level:2.5
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:2.5', 1, '{"location":"Vành Sentinel · Ngã Tư Tuần Tra","briefing":"[NHẬT KÝ CỦA KAI – NGÃ TƯ TUẦN TRA]\nĐây là chỗ hai lộ trình drone cắt nhau. Một drone đứng gác ngay giữa ngã tư. Đèn pha trên tháp thỉnh thoảng quét ngang mặt đường.\nCó ba thứ quyết định tôi qua được hay không: drone cách tôi bao xa, camera của nó đang bật hay tắt, và đèn pha có đang chiếu không.\nLuật qua đường nói được trong một câu: tôi qua được khi drone ở xa hoặc camera tắt, và đèn pha không chiếu.\nCâu đó dễ nói. Cái khó là hiểu chữ \"và\" ăn với phần nào. Chỉ cần đọc sai một lần là drone thấy tôi.","task_steps":["Ba dòng khóa là dữ liệu cảm biến của tình huống đang xét. Mỗi tình huống, game nạp dữ liệu mới vào đó, nên bạn không sửa ba dòng này.","Sửa điều kiện sau `if` cho đúng luật ở ô Mục tiêu. Đọc kỹ xem chữ \"và\" trong luật áp lên phần nào.","Sau mỗi lượt chạy, xem tình huống nào bị phát hiện và dòng nào bị làm mờ. Dòng mờ là dòng không chạy ở tình huống đó.","Bấm CHẠY. Hoàn thành khi qua cả bốn tình huống. Dùng không quá 3 câu lệnh và qua được lượt OMNI đổi luật tuần tra thì được thêm sao."],"objectives":[{"line":1,"label":"Lệnh cho Kai: in LENH: QUA khi drone ở xa hơn 40 mét hoặc camera tắt, và đèn pha không chiếu. Các trường hợp còn lại in LENH: CHO."}],"hints":["Nhìn tình huống bị phát hiện và dòng bị làm mờ. Đọc to luật lên, rồi tự hỏi: khi drone ở xa, điều kiện hiện tại còn xét tới đèn pha không?\nRồi nhìn lại dòng 7: \"camera tắt\" đang được viết thế nào?","Luật có hai phần, nối với nhau bằng chữ \"và\":\n  phần 1: drone ở xa HOẶC camera tắt\n  phần 2: đèn pha không chiếu\nPhần 1 tự nó đã là một lựa chọn \"hoặc\". Python tính \"và\" trước \"hoặc\", nên bạn phải gói phần 1 lại thành một khối rồi mới nối với phần 2:\n  nếu [phần 1] và [phần 2] thì qua, ngược lại thì chờ.","Mảnh tài liệu Python còn đọc được:\nTrue and False              → False\nTrue or False               → True\nnot True                    → False\nTrue or False and False     → True    (and tính trước or)\n(True or False) and False   → False   (trong ngoặc tính trước)\nmua = False\nnot mua                     → True\nMỗi vế của and, or là một giá trị đúng/sai. Muốn nhóm khác thứ tự mặc định thì đặt ngoặc."],"reactions":{"entry":"Ngã Tư Tuần Tra. Một drone gác giữa đường, đèn pha trên tháp quét qua theo nhịp. Luật qua đường có ba phần… Chạy một lần, rồi xem tình huống nào bị phát hiện.","wrong_branch":"Mã đã ra quyết định của một tình huống khác. Luật đúng một phần… nhưng có một phần của điều kiện đang bị xét sai chỗ, hoặc bị lật ngược. Nhìn dòng bị làm mờ.","output_mismatch":"Tình huống {round}, dòng {out_line}. Lệch từ ký tự thứ {col}. Kai không hiểu lệnh này.","output_case_only":"Tình huống {round}, dòng {out_line}. Đúng chữ… sai cỡ chữ. Kai chỉ nhận lệnh viết đúng từng ký tự.","output_missing":"Tình huống {round}. Kai đứng chờ ở mép ngã tư… nhưng không nhận được lệnh nào.","output_extra":"Tình huống {round}. Kai nhận đủ lệnh, rồi còn thêm một dòng ngoài giao thức. Drone nghe thấy dòng thừa đó.","SyntaxError":"Dòng {line}. Trình dịch không đọc được luật này. Chưa tình huống nào chạy.","IndentationError":"Dòng {line}. Lề trái lệch. Với Python, khoảng trắng đầu dòng… là ngữ pháp.","NameError":"Tình huống {round}. Dòng {line}. NameError. Dòng này gọi một cái tên chưa từng có. Soát từng ký tự.","TypeError":"Tình huống {round}. Dòng {line}. TypeError. Dòng này ghép hai giá trị khác kiểu vào cùng một phép toán.","ValueError":"Tình huống {round}. Dòng {line}. ValueError. Giá trị này không đổi được sang kiểu đó.","AttributeError":"Tình huống {round}. Dòng {line}. AttributeError. Giá trị này không có thứ bạn đang gọi.","ZeroDivisionError":"Tình huống {round}. Dòng {line}. Chia cho không. Lõi từ chối.","runtime_error":"Tình huống {round}. Dòng {line}. {error_type}. Chương trình dừng giữa chừng, Kai không nhận được lệnh.","input_unsupported":"Ở ngã tư này không có kênh nhập. Kai chỉ có ba cảm biến… dữ liệu đã nằm sẵn trong đó.","alert_exceeded":"Đúng luật. Nhưng {count} câu lệnh… mỗi lần kiểm hay gán thêm là một lần drone có thể nghe thấy. Luật này gói gọn được trong một câu điều kiện.","wrong_value_counter":"OMNI đổi luật tuần tra. Với dữ liệu mới, lệnh in ra ở dòng {out_line} sai chữ.","counter_error":"OMNI dời chốt gác. Dòng {line}: {error_type}. Mã không chịu được dữ liệu mới.","counter_timeout":"OMNI đổi luật tuần tra. Mã của bạn treo trên dữ liệu mới… Tôi cắt kết nối. Lối qua chỉ mở một nửa.","two_stars":"Qua ngã tư. Drone không quay đầu.","three_stars":"OMNI dời chốt gác. Luật của Kai vẫn đúng.","generic":"Có gì đó không khớp. Đọc lại nhật ký dải tuần tra.","repeated_fail":"Cùng một lỗi, lần thứ {count}. Mở mức gợi ý tiếp theo trong nhật ký.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","timeout":"Mã chạy quá lâu. Tôi cắt kết nối… trước khi drone lần ra dấu.","resource_limit":"Bộ nhớ quá tải. Tôi cắt tiến trình… để laptop còn sống.","blocked_import":"Mô-đun đó bị phong tỏa. Ở ngã tư này, Kai chỉ có ba cảm biến.","system_exit":"Chương trình tự dừng giữa chừng. Kai không nhận được lệnh nào."},"reaction_variants":{"wrong_branch":"Vẫn là quyết định của một tình huống khác. Đặt tình huống bị phát hiện cạnh một tình huống đã qua… chúng khác nhau ở cảm biến nào?","alert_exceeded":"Vẫn {count} câu lệnh. Đếm xem drone có bao nhiêu lần để nghe thấy Kai… rồi gom các lần kiểm lại thành một."},"counter_attack_banner":"OMNI ĐỔI LUẬT TUẦN TRA · DRONE DỜI CHỐT GÁC","outro":"Kai lách qua ngã tư giữa hai lượt đèn. Drone vẫn đứng giữa đường, camera quay sang hướng khác.\nDưới chân cột đèn có một hộp điều khiển cũ, nắp đã gỉ. Bên trong vẫn lưu lịch tuần tra, kèm một dòng nhật ký:","lore_fragment":"KTS-03: Lịch tuần tra gốc do tám người chúng tôi viết, từng phút một. OMNI chưa bao giờ đổi nó. Chẳng ai đi đổi một thứ đã đúng.","component":"Điều kiện qua đường","outro_beats":[{"kind":"echo","text":"Tôi vừa so lịch vượt rào mà 0xA7 gửi lúc bạn mới tới Vành Sentinel với các luật bạn vừa giải. Hai bên khớp nhau tới từng giây."},{"kind":"echo","text":"…Lịch đó chỉ có trong hộp điều khiển gốc."},{"kind":"kai","text":"Tôi nhớ lời KTS-03 dặn ở Cổng phía Bắc: đừng tin tín hiệu nào mang mã 0xA7."},{"kind":"log","text":"Kai đi tiếp về phía Trạm Sạc Drone. Trên bức tường cạnh trạm, bảng lệnh của tháp đang sáng lên từng dòng."}],"knowledge_summary":{"title":"Điều kiện ghép: and, or, not","sections":[{"heading":"`and`: cả hai vế phải đúng","body":"`a and b` cho `True` khi cả `a` và `b` đều đúng. Chỉ cần một vế sai là kết quả thành `False`."},{"heading":"`or`: chỉ cần một vế đúng","body":"`a or b` cho `True` khi ít nhất một vế đúng. Kết quả chỉ là `False` khi cả hai vế đều sai."},{"heading":"`not` đảo một giá trị","body":"`not x` cho `True` khi `x` là `False`, và ngược lại. `not` chỉ áp lên giá trị đứng ngay sau nó."},{"heading":"Thứ tự tính và dấu ngoặc","body":"Python tính `not` trước, rồi tới `and`, sau cùng mới tới `or`. Vì vậy `True or False and False` được tính như `True or (False and False)`.\nMuốn nhóm theo cách khác thì đặt ngoặc: phần trong ngoặc được tính trước."},{"heading":"Điều kiện ghép trong `if`","body":"Một câu `if` với điều kiện ghép thay được cho nhiều câu `if` nối nhau. Mỗi vế phải là một phép so sánh đầy đủ, hoặc một giá trị đúng/sai."}],"mistakes":[{"code":"a = 5\nif a > 0 && a < 10:\n    print(a)","explain":"Python dùng chữ `and`, `or`, `not`. Các ký hiệu `&&`, `||`, `!` của ngôn ngữ khác là lỗi cú pháp."},{"code":"nong = True\nmua = False\nco_o = False\nprint(nong or mua and co_o)","explain":"Người viết muốn \"(nóng hoặc mưa) và có ô\". Không có ngoặc thì `and` được tính trước, nên Python hiểu thành \"nóng, hoặc (mưa và có ô)\". Viết `(nong or mua) and co_o`."},{"code":"x = 5\nif x == 1 or 2:\n    print(\"Dung\")","explain":"Vế sau `or` là `2`, không phải `x == 2`. Python coi số `2` là đúng, nên điều kiện luôn đúng. Mỗi vế phải là một phép so sánh đầy đủ: `x == 1 or x == 2`."}],"next":"Màn sau: một câu hỏi chỉ có nghĩa khi câu hỏi trước đã có câu trả lời. Bạn sẽ đặt một `if` bên trong một `if` khác, và xét một dòng trống đọc từ kênh nhập."}}', '2026-10-29T19:58:52.034Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.5' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
